"""Write a PTX file as a Lean `PTX.Syntax.Module` definition.

Python only tokenizes and parses. Opcode modifiers, literal values, labels and
register declarations are interpreted by the Lean decoder, not here.
"""

import argparse
import json
from pathlib import Path

from lean_wrap import WIDTH, wrap_lines
from parse_ptx import Operand, Statement, parse

SYNTAX_LEAN = Path(__file__).resolve().parents[1] / "Core" / "Source" / "Syntax.lean"
LICENSE = SYNTAX_LEAN.read_text().split("\n")[0] + "\n"


# Written to a generated file whose names do not fit a line. `Tools/check_lean_text.py` skips
# the width check of a file that contains it, as the Lean linter does.
NO_LONG_LINE = "set_option linter.style.longLine false"
# The names of its definitions also contain `__`, which Mathlib's name linter reports.
NO_NAME_CHECK = "set_option linter.style.nameCheck false"


def string(text: str) -> str:
    return json.dumps(text, ensure_ascii=True)


def strings(items) -> str:
    return "[" + ", ".join(string(x) for x in items) + "]"


def operand(op: Operand) -> str:
    kids = "[" + ", ".join(operand(c) for c in op.children) + "]"
    if op.kind == "register":
        return f"(.register {string(op.text)})"
    if op.kind == "symbol":
        return f"(.symbol {string(op.text)})"
    if op.kind == "literal":
        return f"(.literal {string(op.text)})"
    if op.kind == "sink":
        return ".sink"
    if op.kind in ("address", "vector", "pair"):
        return f"(.{op.kind} {kids})"
    if op.kind == "offset":
        return f"(.offset {string(op.text)} {operand(op.children[0])} {operand(op.children[1])})"
    if op.kind == "not":
        return f"(.negate {operand(op.children[0])})"
    raise ValueError(f"unknown operand kind {op.kind}")


def statement(s: Statement, indent: str) -> str:
    if s.kind == "instruction":
        pred = "none"
        if s.predicate:
            pred = f"(some ({string(s.predicate)}, {str(s.negated).lower()}))"
        ops = "[" + ", ".join(operand(o) for o in s.operands) + "]"
        return f".instruction {pred} {string(s.opcode)} {ops}"
    if s.kind == "label":
        return f".label {string(s.text)}"
    if s.kind in ("declaration", "directive"):
        return f".{s.kind} {strings(s.tokens)}"
    if s.kind == "scope":
        return ".scope " + body(s.body, indent + "  ")
    raise ValueError(f"unknown statement kind {s.kind}")


def body(stmts, indent: str) -> str:
    inner = (",\n" + indent + "  ").join(statement(s, indent + "  ") for s in stmts)
    return f"[\n{indent}  {inner}\n{indent}]"


# Statements (counting those inside scopes) per compiled definition. The recursion depth
# of Lean's code generator grows with the size of a definition, and it exhausts the
# default `maxRecDepth` at roughly a thousand statements, so a longer function body is split
# into `<function>_body<k>` definitions of at most this weight, joined with `++`.
CHUNK = 512


def weight(s: Statement) -> int:
    return 1 + (sum(weight(c) for c in s.body) if s.kind == "scope" else 0)


def chunks(stmts):
    parts, part, total = [], [], 0
    for s in stmts:
        if part and total + weight(s) > CHUNK:
            parts.append(part)
            part, total = [], 0
        part.append(s)
        total += weight(s)
    return parts + [part]


def export(source: str, namespace: str) -> str:
    program = parse(source)
    lines = [
        LICENSE,
        "-- Generated by Tools/export_lean.py. Do not edit.",
        "module",
        "",
    ]
    lines += [
        "public import Core.Source.Syntax",
        "",
        "@[expose] public section",
        "",
        f"namespace {namespace}",
        "open PTX.Syntax",
        "",
    ]
    for f in program.functions:
        if f.declaration:
            raise ValueError(f"function declaration {f.name} is not supported")
        parts = chunks(f.body)
        if len(parts) == 1:
            value = body(f.body, "  ")
        else:
            names = [f"{f.name}_body{k}" for k in range(len(parts))]
            for name, part in zip(names, parts):
                lines.append(f"def {name} : List Statement := {body(part, '')}")
                lines.append("")
            value = " ++ ".join(names)
        lines.append(f"def {f.name} : Function where")
        lines.append(f"  name := {string(f.name)}")
        lines.append(f"  header := {strings(f.header)}")
        lines.append(f"  body := {value}")
        lines.append("")
    funcs = ", ".join(f.name for f in program.functions)
    directives = []
    for index, tokens in enumerate(program.directives):
        if len(tokens) <= CHUNK:
            directives.append(strings(tokens))
            continue
        # nvcc line information can include hundreds of thousands of .debug_str tokens.
        # A single Lean list literal of that size exhausts the elaborator heartbeat limit.
        separator = " "
        while any(separator in token for token in tokens):
            separator += "|"
        name = f"directiveTokens{index}"
        # Target validation reads the directive name without unpacking the debug payload.
        packed = [separator.join(tokens[i : i + 2048]) for i in range(1, len(tokens), 2048)]
        lines += [
            f"def {name} : List String :=",
            f"  {string(tokens[0])} :: ({strings(packed)} : List String).flatMap "
            f"(fun s => s.splitOn {string(separator)})",
            "",
        ]
        directives.append(name)
    lines.append("def module : Module where")
    lines.append(f"  sourceSha256 := {string(program.source_sha256)}")
    lines.append("  directives := [" + ", ".join(directives) + "]")
    lines.append("  globals := [" + ", ".join(strings(g) for g in program.globals) + "]")
    lines.append(f"  functions := [{funcs}]")
    lines += ["", f"end {namespace}", ""]
    lines = wrap_lines("\n".join(lines).split("\n"), step=2)
    if any(len(x) > WIDTH for x in lines):
        # a PTX name that is longer than a line (Lean identifiers cannot be broken)
        at = lines.index("open PTX.Syntax") + 1
        lines[at:at] = ["", NO_LONG_LINE, NO_NAME_CHECK]
        at = lines.index("public import Core.Source.Syntax") + 1
        lines[at:at] = [
            "import Mathlib.Tactic.Linter.Style  -- for the option `linter.style.longLine`"
        ]
    return "\n".join(lines)


def main():
    cli = argparse.ArgumentParser(description=__doc__)
    cli.add_argument("ptx", type=Path)
    cli.add_argument("-o", "--output", type=Path, required=True)
    cli.add_argument("--namespace", required=True)
    args = cli.parse_args()
    args.output.write_text(export(args.ptx.read_text(), args.namespace))
    print(f"wrote {args.output}")


if __name__ == "__main__":
    main()
